import * as actions from '../currency-action/currency.actions';
import { CurrencyRecordState } from './currency.state';
import { CurrencyListResponseModel } from '../currency-model/currencylist.response.model';
import { CurrencyNewResponse } from '../currency-model/currencynewResponse.model';
export const initialState = new CurrencyRecordState();
export function reducer(state = initialState, {
  type,
  payload
}) {
  if (!type) {
    return state;
  }

  switch (type) {
    case actions.ActionTypes.DO_CURRENCY_LIST:
      {
        return Object.assign({}, state, {
          listLoading: true,
          listLoaded: false,
          listFailed: false
        });
      }

    case actions.ActionTypes.DO_CURRENCY_LIST_COUNT:
      {
        return Object.assign({}, state, {
          countLoading: true,
          countLoaded: false,
          countFailed: false
        });
      }

    case actions.ActionTypes.DO_CURRENCY_LIST_NEW:
      {
        return Object.assign({}, state, {
          addLoading: true,
          addLoaded: false,
          addFailed: false
        });
      }

    case actions.ActionTypes.DO_CURRENCY_UPDATE:
      {
        return Object.assign({}, state, {
          updateLoading: true,
          updateLoaded: false,
          updateFailed: false
        });
      }

    case actions.ActionTypes.DO_CURRENCY_DELETE:
      {
        return Object.assign({}, state, {
          deleteLoading: true,
          deleteLoaded: false,
          deleteFailed: false
        });
      }

    case actions.ActionTypes.DO_CURRENCY_LIST_SUCCESS:
      {
        const currencyList = payload.data.map(_currency => {
          const tempListModel = new CurrencyListResponseModel(_currency);
          return tempListModel;
        });
        return Object.assign({}, state, {
          currencyList: currencyList,
          listLoading: false,
          listLoaded: true,
          listFailed: false
        });
      }

    case actions.ActionTypes.DO_CURRENCY_LIST_COUNT_SUCCESS:
      {
        return Object.assign({}, state, {
          currencyListCount: payload,
          countLoading: false,
          countLoaded: true,
          countFailed: false
        });
      }

    case actions.ActionTypes.DO_CURRENCY_LIST_NEW_SUCCESS:
      {
        const newCurrency = new CurrencyNewResponse(payload.data);
        return Object.assign({}, state, {
          currencyNew: payload,
          currencyNewdetail: newCurrency,
          addLoading: false,
          addLoaded: true,
          addFailed: false
        });
      }

    case actions.ActionTypes.DO_CURRENCY_UPDATE_SUCCESS:
      {
        return Object.assign({}, state, {
          currencyupdate: payload.user,
          updateLoading: false,
          updateLoaded: true,
          updateFailed: false
        });
      }

    case actions.ActionTypes.DO_CURRENCY_DELETE_SUCCESS:
      {
        return Object.assign({}, state, {
          currencyDelete: payload,
          deleteLoading: false,
          deleteLoaded: true,
          deleteFailed: false
        });
      }

    case actions.ActionTypes.DO_CURRENCY_LIST_FAIL:
      {
        return Object.assign({}, state, {
          listLoading: false,
          listLoaded: true,
          listFailed: true
        });
      }

    case actions.ActionTypes.DO_CURRENCY_LIST_NEW_FAIL:
      {
        return Object.assign({}, state, {
          updateLoading: false,
          updateLoaded: true,
          updateFailed: true
        });
      }

    case actions.ActionTypes.DO_CURRENCY_UPDATE_FAIL:
      {
        return Object.assign({}, state, {
          updateLoading: false,
          updateLoaded: true,
          updateFailed: true
        });
      }

    case actions.ActionTypes.DO_CURRENCY_DELETE_FAIL:
      {
        return Object.assign({}, state, {
          deleteLoading: false,
          deleteLoaded: true,
          deleteFailed: true
        });
      }

    case actions.ActionTypes.DO_CURRENCY_LIST_COUNT_FAIL:
      {
        return Object.assign({}, state, {
          countLoading: false,
          countLoaded: true,
          countFailed: true
        });
      }

    default:
      {
        return state;
      }
  }
}
export const getCurrencyList = state => state.currencyList;
export const getCurrencyListCount = state => state.currencyListCount;
export const getCurrencyNew = state => state.currencyNew;
export const getCurrencyNewdetail = state => state.currencyNewdetail;
export const getCurrencyUpdate = state => state.currencyupdate;
export const getCurrencyDelete = state => state.currencyDelete;
export const getCurrencyListLoading = state => state.listLoading;
export const getCurrencyListLoaded = state => state.listLoaded;
export const getCurrencyListFailed = state => state.listFailed;
export const getCurrencyCountLoading = state => state.countLoading;
export const getCurrencyCountLoaded = state => state.countLoaded;
export const getCurrencyCountFailed = state => state.countFailed;
export const getCurrencyAddLoading = state => state.addLoading;
export const getCurrencyAddLoaded = state => state.addLoaded;
export const getCurrencyAddFailed = state => state.addFailed;
export const getCurrencyUpdateLoading = state => state.updateLoading;
export const getCurrencyUpdateLoaded = state => state.updateLoaded;
export const getCurrencyUpdateFailed = state => state.updateFailed;
export const getCurrencyDeleteLoading = state => state.deleteLoading;
export const getCurrencyDeleteLoaded = state => state.deleteLoaded;
export const getCurrencyDeleteFailed = state => state.deleteFailed;
